import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const corpus = JSON.parse(readFileSync('portability/corpus/group-canonical-order.json', 'utf8'));
// Independent restricted numeric/null model. Expected tuples and multiplicities
// are authored fixtures, never generated by a lowerer or reference evaluator.
function enumerate(rows, by) {
  const groups = new Map();
  if (by.length === 0) groups.set('[]', { key: [], count: 0 });
  for (const row of rows) {
    const key = by.map(name => {
      assert.ok(Object.hasOwn(row, name));
      const value = row[name];
      assert.ok(value === null || (typeof value === 'number' && Number.isFinite(value)));
      return value;
    });
    const id = JSON.stringify(key);
    const group = groups.get(id) ?? { key, count: 0 };
    group.count++;
    groups.set(id, group);
  }
  return [...groups.values()].sort((a, b) => {
    for (let i = 0; i < by.length; i++) {
      const left = a.key[i], right = b.key[i];
      if (left === right) continue;
      if (left === null) return -1;
      if (right === null) return 1;
      return left < right ? -1 : 1;
    }
    return 0;
  });
}
for (const f of corpus.cases) test(f.id, () => {
  for (const rows of [f.rows, [...f.rows].reverse()]) {
    const groups = enumerate(rows, f.by);
    assert.deepEqual(groups.map(g => g.key), f.expected_keys);
    assert.deepEqual(groups.map(g => g.count), f.expected_counts);
    // Empty aggregates have the same final key enumeration, without count fields.
    assert.deepEqual(groups.map(g => Object.fromEntries(f.by.map((k, i) => [k, g.key[i]]))),
      f.expected_keys.map(key => Object.fromEntries(f.by.map((k, i) => [k, key[i]]))));
  }
});
test('group order is explicit and does not rewrite the primitive null law', () => {
  const text = readFileSync('docs/spec/language.md', 'utf8');
  assert.match(text, /lexicographically in authored `by` order, with\nNULLS FIRST independently at every component/);
  const laws = JSON.parse(readFileSync('spec/dependencies/aoa-rela-primitive-laws.json', 'utf8'));
  assert.equal(laws.operators['REL.groupBy'].null_law, 'null group keys are first-class group key values');
});
